import{_ as i,o as u,c as n,a2 as k}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Nakala 251·Uchambuzi wa Mfumo wa Táng Luó · Jumla ya Dari Tatu na Tathmini ya Upekee wa Mhusika Mkuu","description":"","frontmatter":{"title":"Nakala 251·Uchambuzi wa Mfumo wa Táng Luó · Jumla ya Dari Tatu na Tathmini ya Upekee wa Mhusika Mkuu","no":251,"module":2,"tags":["唐罗","体系拆解","三重上限","主角唯一性"],"related":["17-位面至高强者标准","04-反掠夺主义核心论纲","08-人人有路保障体系"]},"headers":[],"relativePath":"sw/251_模块2-唐罗体系拆解-总论三重上限与主角唯一性评判.md","filePath":"sw/251_模块2-唐罗体系拆解-总论三重上限与主角唯一性评判.md"}'),e={name:"sw/251_模块2-唐罗体系拆解-总论三重上限与主角唯一性评判.md"};function m(h,a,o,w,t,l){return u(),n("div",null,[...a[0]||(a[0]=[k('<h1 id="nakala-251·uchambuzi-wa-mfumo-wa-tang-luo-jumla-ya-dari-tatu-na-tathmini-ya-upekee-wa-mhusika-mkuu" tabindex="-1">Nakala 251·Uchambuzi wa Mfumo wa Táng Luó: Jumla ya Dari Tatu na Tathmini ya Upekee wa Mhusika Mkuu <a class="header-anchor" href="#nakala-251·uchambuzi-wa-mfumo-wa-tang-luo-jumla-ya-dari-tatu-na-tathmini-ya-upekee-wa-mhusika-mkuu" aria-label="Permalink to &quot;Nakala 251·Uchambuzi wa Mfumo wa Táng Luó: Jumla ya Dari Tatu na Tathmini ya Upekee wa Mhusika Mkuu&quot;">​</a></h1><ul><li>Moduli: Moduli ya Pili · Kuchambua Mfumo wa Rejeo | Msingi wa Rejeo: Hati 17, 04, 08</li></ul><h2 id="utangulizi-kwa-nini-kumchambua-tang-luo" tabindex="-1">Utangulizi: Kwa nini kumchambua Táng Luó? <a class="header-anchor" href="#utangulizi-kwa-nini-kumchambua-tang-luo" aria-label="Permalink to &quot;Utangulizi: Kwa nini kumchambua Táng Luó?&quot;">​</a></h2><p>Táng Luó ndiye mhusika mkuu wa &#39;Ninaweza Kuona Nguvu ya Kupambana&#39;, muasisi wa mfumo wa mafunzo aina ya &#39;Chuo cha Wúshuāng&#39; baada ya kufikia kilele cha mafunzo. Kwa nini hasa kumchambua Táng Luó kama ulinganisho wa Ustaarabu wa Usawa wa Nanga? Kwa sababu Táng Luó anawakilisha aina ya &#39;mhusika mkuu mwema aliyeshinda katika hali ngumu&#39; — dari ya juu zaidi ambayo ustaarabu wa kutoa zawadi umewahi kufikia. Kuchambua dari yake inamaanisha kujibu swali: hata kama Táng Luó kamilifu atatokea, ustaarabu unaweza kwenda juu kiasi gani?</p><p>Makala hii inachambua dari tatu za mfumo wa Táng Luó na &#39;upekee wa mhusika mkuu&#39; kama kasoro ya kimuundo, kisha inalinganisha na Mfumo wa Uhakikisho wa &#39;Njia kwa Kila Mtu&#39; wa Ustaarabu wa Usawa wa Nanga.</p><p>Kanuni Muhimu Sita za Juu hufanya kazi kama lenzi ya uchambuzi: Kanuni ya Kupinga Unyanyasaji — Táng Luó awe mwema kiasi gani, mfumo anaoketi bado ni urithi wa ulimwengu wa uwindaji wa zamani; Kanuni ya Jamhuri ya Kabila Kumi na Elfu — chini ya mantiki ya Táng Luó, viumbe wote wanategemea ushujaa wa mtu binafsi; Kanuni ya Kupanda Mwelekeo kwa Pamoja — kupanda kwa mhusika mkuu si kupanda kwa wote, kuzuia kipaji kikubwa kutumika kidogo; Kanuni ya Nidhamu ya Sababu-Natija — muundo wa kuamini shujaa ndio unaosababisha hatari ya &#39;mwenye nguvu akijiu, ustaarabu unarudi nyuma&#39;; Kanuni ya Kipaumbele cha Sheria — mfumo wa sheria wa uchambuzi wa mfumo wa Táng Luó ni thabiti na wenyewe, bila kubadilishwa kwa urahisi wa hadithi, unaweza kupanuka bila kikomo bila kuporomoka. Kanuni ya Usawa wa Ukombozi wa Kila Kiumbe inasisitiza kila mtu ana Nguvu Isiyo na Mwisho ya Msingi; wanafunzi wavivu wanabaki na nguvu ya msingi ya uhakika na hawataondolewa na wakati, wakati wenye tamaa na Vijana Wakuu wanaweza kuongeza ngazi za juu za nguvu ya bila kikomo; asili ya nguvu ya bila kikomo ni ya kila mtu, na unyanyasaji kawaida hupoteza maana.</p><h2 id="i-dari-tatu-za-mfumo-wa-tang-luo" tabindex="-1">I. Dari Tatu za Mfumo wa Táng Luó <a class="header-anchor" href="#i-dari-tatu-za-mfumo-wa-tang-luo" aria-label="Permalink to &quot;I. Dari Tatu za Mfumo wa Táng Luó&quot;">​</a></h2><ol><li>Dari ya nguvu: Táng Luó alifika kilele cha mafunzo katika ulimwengu wake, lakini nguvu yake ni yake tu. Chuo cha Wúshuāang hakizai Wúshuāang, kinazai wanafunzi wanaotegemea kivuli cha Táng Luó. Dari ya mwanafunzi ni kiuno cha Táng Luó</li><li>Dari ya mfumo: Táng Luó anakuza ustawi, lakini ustawi bado unatolewa kutoka juu kwenda chini. Anayepokea zawadi anaweza tu kushukuru, hawezi kujenga pamoja. Chanzo cha ustawi kinategemea wema wa mhusika mkuu; wema unabadilika, mpangilio unabadilika</li><li>Dari ya ustaarabu: Mfumo wa Táng Luó unarithi vuguvugu la ulimwengu wa uwindaji wa zamani — rasilimali chache, ngazi ya nguvu-dhaifu, mhusika mkuu kama injini pekee. Hata Táng Luó kamilifu haepi kurejea kihistoria akifariki. &#39;Upekee wa mhusika mkuu&#39; ni jeraha la kimuundo la mfumo</li></ol><h2 id="ii-upekee-wa-mhusika-mkuu-ni-nini" tabindex="-1">II. &#39;Upekee wa Mhusika Mkuu&#39; ni Nini? <a class="header-anchor" href="#ii-upekee-wa-mhusika-mkuu-ni-nini" aria-label="Permalink to &quot;II. &#39;Upekee wa Mhusika Mkuu&#39; ni Nini?&quot;">​</a></h2><p>Upekee wa mhusika mkuu unamaanisha: utendaji wote wa kawaida na endelevu wa ustaarabu unategemea mtu mmoja wa kati. Hakuna taasisi inayojiendesha, hakuna mpangilio unaojitolea. Táng Luó akiwa hai, yote yanaenda; Táng Luó akifariki, ustaarabu unarudi kwenye machafuko.</p><p>Muundo huu hauzaliwi kwa uovu wa mhusika mkuu, bali kwa muundo wa mfumo: mfumo haukuandika mpangilio katika mikataba, mahakama, mitandao ya nanga; uliandika mpangilio katika mhusika mkuu mwenyewe. Kwa sababu Táng Luó ni mwenye nguvu zaidi, jamii haina motisha ya kujenga taasisi zinazojitegemea — kwa sababu Táng Luó tayari amesuluhisha kila kitu. Hii ni dhihaka: mhusika mkuu mwenye nguvu zaidi, anageuka kuwa udhaifu mkubwa zaidi wa mfumo.</p><h2 id="iii-ulinganisho-na-mfumo-wa-uhakikisho-wa-njia-kwa-kila-mtu" tabindex="-1">III. Ulinganisho na Mfumo wa Uhakikisho wa &#39;Njia kwa Kila Mtu&#39; <a class="header-anchor" href="#iii-ulinganisho-na-mfumo-wa-uhakikisho-wa-njia-kwa-kila-mtu" aria-label="Permalink to &quot;III. Ulinganisho na Mfumo wa Uhakikisho wa &#39;Njia kwa Kila Mtu&#39;&quot;">​</a></h2><p>Ustaarabu wa Usawa wa Nanga unaacha upekee wa mhusika mkuu na unachukua Mfumo wa Uhakikisho wa &#39;Njia kwa Kila Mtu&#39;:</p><ul><li>Kuhusu chanzo cha nguvu: chanzo cha nguvu ya Táng Luó ni mtu binafsi; chanzo cha nguvu ya mfumo wa Nanga ni mtandao wa nanga wa kila mtu. Hakuna anayeweza kubadilishwa, hakuna chanzo pekee</li><li>Kuhusu endelevu: endelevu ya Táng Luó inategemea yeye mwenyewe; endelevu ya mfumo wa Nanga inategemea taasisi. Hata Mwenye Nguvu Mkuu wa Njia mwenye nguvu zaidi akifariki, mtandao unaendelea kufanya kazi</li><li>Kuhusu ustawi: ustawi wa Táng Luó ni zawadi, kutoka juu kwenda chini, unategemea wema; ustawi wa mfumo wa Nanga ni ujenzi, kutoka chini kwenda juu, kupitia Mfumo wa Mkataba unaohusishwa na Uzalishaji, kila mtu huchangia na kila mtu anapokea</li><li>Kuhusu hatima: mfumo wa Táng Luó unaisha wakati mhusika mkuu anafariki; mfumo wa Nanga unaendelea kupanuka bila kikomo hadi Nguvu ya Nanga ya anga nyingi zaidi</li></ul><h2 id="iv-kwa-nini-hata-mhusika-mkuu-mwema-hawezi-kuokoa-mfumo" tabindex="-1">IV. Kwa nini hata mhusika mkuu mwema hawezi kuokoa mfumo <a class="header-anchor" href="#iv-kwa-nini-hata-mhusika-mkuu-mwema-hawezi-kuokoa-mfumo" aria-label="Permalink to &quot;IV. Kwa nini hata mhusika mkuu mwema hawezi kuokoa mfumo&quot;">​</a></h2><p>Lazima tukabiliane na hitimisho gumu: hata Táng Luó kamilifu, mkweli, mwema, tayari kujitoa maisha yake kulinda kila mtu, bado hawezi kuokoa mfumo kutoka kwa dari ya upekee wa mhusika mkuu. Sababu ni rahisi: tatizo la Táng Luó si asili yake, bali muundo wa mfumo alioujenga. Mtu mwenye nguvu, hata akikuwa kamilifu, hawezi kuchukua nafasi ya taasisi mia moja.</p><p>Na mbaya zaidi: kadri mhusika mkuu anavyokuwa kamilifu na mwenye uwezo, ndivyo jamii inavyozoea kumtegemea. Hakuna anayejifunza kujenga kwa kujitegemea, hakuna anayejifunza kuchukua wajibu. Wakati mhusika mkuu hatimaye anaondoka, jamii inajikuta haijajiandaa kabisa. Hii ndiyo &#39;laana ya mhusika mkuu kamilifu&#39;: ukamilifu wake ni gereza la ustaarabu.</p><h2 id="v-njia-sahihi-jenga-taasisi-si-kukuza-mashujaa" tabindex="-1">V. Njia Sahihi: Jenga Taasisi, Si Kukuza Mashujaa <a class="header-anchor" href="#v-njia-sahihi-jenga-taasisi-si-kukuza-mashujaa" aria-label="Permalink to &quot;V. Njia Sahihi: Jenga Taasisi, Si Kukuza Mashujaa&quot;">​</a></h2><p>Ustaarabu wa Usawa wa Nanga unajibu: badala ya kukuza mhusika mkuu mmoja kamilifu, ni bora kujenga taasisi zinazowawezesha watu wa kawaida milioni moja kufanya mazoezi kwa amani. Njia sahihi si &#39;kuzaa Táng Luó mwingine&#39;, bali &#39;kufanya hakuna mtu anayehitaji kuwa Táng Luó tena&#39;.</p><p>Hii ndiyo kupanda kwa kweli kwa Ustaarabu wa Usawa wa Nanga juu ya mifumo yote ya mhusika mkuu pekee: haitafuti mtu mwenye nguvu zaidi, bali inatafuta mfumo unaolinda zaidi. Haitaki shujaa wa milele, inataka mpangilio usiyotegemea shujaa yeyote.</p><h2 id="vi-pointi-tano-za-msingi" tabindex="-1">VI. Pointi Tano za Msingi <a class="header-anchor" href="#vi-pointi-tano-za-msingi" aria-label="Permalink to &quot;VI. Pointi Tano za Msingi&quot;">​</a></h2><ul><li>Kupinga uharibifu wa nishati: kutegemea mhusika mkuu mmoja hufanya watu milioni moja wa kawaida wasiendeleze uwezo; mfumo wa Nanga unawasha kila mmoja</li><li>Kupinga unyanyasaji: mfumo wa Táng Luó, uwe mwema kiasi gani, bado unarithi ulimwengu wa uwindaji; mfumo wa Nanga unakatiza vuguvugu la unyanyasaji kutoka mzizi</li><li>Kulinganisha dari ya Táng Luó: dari ya mfumo wa Táng Luó ni Táng Luó mwenyewe; dari ya mfumo wa Nanga ni kupanuka bila kikomo hadi anga nyingi zaidi</li><li>Kufunika kwa Kabila Kumi na Elfu: mfumo wa Táng Luó unafunika wale wanaoonekana na Táng Luó; mfumo wa Nanga unafunika 99% ya viumbe wote, bila ubaguzi</li><li>Ufunguzi wa kina wa anga nyingi zaidi: mfumo wa Táng Luó unategemea mhusika mkuu kufunga mlango; mfumo wa Nanga unafungua kila hatua kwa umma na kwa pamoja</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Kumchambua Táng Luó sio kumdhalilisha shujaa, bali kujibu swali la kimuundo: shujaa mwema anaweza kuokoa ustaarabu? Jibu la Ustaarabu wa Usawa wa Nanga: Anaweza kuokoa watu wachache, hawezi kuokoa ustaarabu. Kwa sababu ustaarabu hauhitaji shujaa mmoja, unahitaji mamilioni ya watu wa kawaida wanaoweza kutembea, kufanya mazoezi, kujenga, na wakati shujaa akifariki, kuendelea kutembea. Hii ndiyo maana ya kweli ya &#39;Njia kwa Kila Mtu&#39;: si shujaa mmoja akifungua njia kwa wote, bali wote wakifungua njia kwa wote.</p><h2 id="husika" tabindex="-1">Husika <a class="header-anchor" href="#husika" aria-label="Permalink to &quot;Husika&quot;">​</a></h2><ul><li>Hati zinazohusiana: <a href="./17-位面至高强者标准.html">17-位面至高强者标准</a> · <a href="./04-反掠夺主义核心论纲.html">04-反掠夺主义核心论纲</a> · <a href="./08-人人有路保障体系.html">08-人人有路保障体系</a></li><li>Tovuti rasmi: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',26)])])}const r=i(e,[["render",m]]);export{g as __pageData,r as default};
